      }]
    };
  },
  created() {
    // 根据URL查询参数设置当前活动的标签页
    const tab = this.$route.query.tab;
    if (tab) {
      this.activeTab = tab;
    }
  },
  watch: {
    // 监听路由变化，更新活动标签页
    '$route.query.tab': function (newTab) {
      if (newTab) {
        this.activeTab = newTab;
      } else {
        this.activeTab = 'majors';
      }
    }
  },
  methods: {
    handleSelect(key) {
      this.activeTab = key;
      // 更新URL查询参数
      this.$router.push({
        path: '/teaching',
        query: {
          tab: key
        }
      }).catch(err => {
        if (err.name !== 'NavigationDuplicated') {
          throw err;
        }
      });
    }
  }
};
